1443	// ===================== persistent continuous-ring prefill (hd128 bf16 TMA) =====================
1444	// FA3-style persistent kernel: each CTA grabs work-items off a static stride (work = blockIdx.x +
1445	// k*gridDim.x) and processes them in a loop. The win vs the per-tile prefill_kernel is that the K/V
1446	// ring is ONE CONTINUOUS stream across work-items -- PipelineState (the ring index g + its phase) is
1447	// declared once and NEVER reset per item, so the producer prefetches the next item's K/V into slots
1448	// the consumer just freed, with no per-item pipeline-fill bubble. (The earlier naive per-item-reinit
1449	// persistent attempt regressed precisely because it paid that fill + barrier-reinit cost every item.)
1450	//
1451	// Q is single-buffered with a barQf/barQe ping-pong (phase = witer&1): the producer waits barQe (the
1452	// consumer freed the prior Q), reloads Q -- via ONE async TMA box-set (rep==1, mapQ) so the reload is
1453	// cheap enough to hide behind the continuous ring; GQA/paged would fall back to the cp.async gather --
1454	// then signals barQf. To keep the ring primed across the boundary the producer issues the item's FIRST
1455	// K/V tile (empty-gated on the global g, NOT Q-gated) BEFORE the barQe wait, then floods the rest after
1456	// Q. Stage index / phase everywhere use the GLOBAL counter g so
1457	// producer and consumer stay in lock-step (both advance g by n_cnt per non-empty item, skip empties
1458	// identically). num_splits is implicitly 1 (prefill); no split-KV epilogue. TMA-only (routed so).
1459	template <typename TIn, typename TC, int HD, int HDV, bool USE_TMA, bool EXTRA, int STAGES, int CN = CTA_N,
1460	          int CM = CTA_M, int MINB = 1, bool TMA_Q = USE_TMA>
1461	__global__ __launch_bounds__(WG * (1 + CM / 64), MINB) void prefill_persist_kernel(
1462	        const TIn* __restrict__ Q, const TIn* __restrict__ K,
1463	        const TIn* __restrict__ V, TC* __restrict__ O, float* __restrict__ LSE,
1464	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
1465	        const int* __restrict__ page_table,
1466	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head, long o_row, long o_head,
1467	        int hkv, int rep, int total_q, int block_size, int page_stride,
1468	        float scale, int causal, float softcap, int win_l, int win_r,
1469	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
1470	        const float* __restrict__ v_descale, int ds_b, int ds_h,
1471	        int tiles_m, int batch, int* __restrict__ work_ctr, const float* __restrict__ s_aux,
1472	        const __grid_constant__ CUtensorMap mapK, const __grid_constant__ CUtensorMap mapV,
1473	        const __grid_constant__ CUtensorMap mapQ) {
1474	    constexpr int HDsm  = ((HD  + 63) / 64) * 64;
1475	    constexpr int HDVsm = ((HDV + 63) / 64) * 64;
1476	    constexpr int KSTRIDE = CN * HDsm;
1477	    constexpr int VSTRIDE = CN * HDVsm;
1478	    constexpr int NCONS = (CM / 64) * WG;
1479	
1480	    constexpr int QBUF = 1;                    // Single Q buffer: rep==1 Q is reloaded via ONE async TMA
1481	                                               // (mapQ), fast enough that the STAGES-deep continuous K/V
1482	                                               // ring hides it across the item boundary. Double-Q hid the
1483	                                               // reload too but forced STAGES=2 (smem) -> starved K/V.
1484	    constexpr int SDEPTH = 2;                  // dynamic-scheduler work FIFO depth (producer lookahead)
1485	    TC* sQ = reinterpret_cast<TC*>(pf_smem);
1486	    TC* sK0 = sQ + QBUF * CM * HDsm;
1487	    TC* sV0 = sK0 + STAGES * KSTRIDE;
1488	    uint64_t* bars = reinterpret_cast<uint64_t*>(sV0 + STAGES * VSTRIDE);
1489	    uint64_t* full = bars;                     // [STAGES] count 1 (TMA tx-barrier)
1490	    uint64_t* empty = bars + STAGES;           // [STAGES] count NCONS
1491	    uint64_t* barQf = bars + 2 * STAGES;       // [QBUF] Q ready (producer -> consumers), count NumProd
1492	    uint64_t* barQe = bars + 2 * STAGES + QBUF;// [QBUF] Q free  (consumers -> producer), count NCONS
1493	    uint64_t* schF = bars + 2 * STAGES + 2 * QBUF;          // [SDEPTH] work ready (producer -> consumers)
1494	    uint64_t* schE = bars + 2 * STAGES + 2 * QBUF + SDEPTH; // [SDEPTH] slot free (consumers -> producer)
1495	    int* schW = reinterpret_cast<int*>(bars + 2 * STAGES + 2 * QBUF + 2 * SDEPTH);  // [SDEPTH] grabbed work idx
1496	
1497	    // Q via single async TMA when KV is contiguous (non-paged): rep==1 uses one 2D [CM,64] box per
1498	    // col-block; packed-GQA (rep>1, rep|CM) uses one 3D [64,rep,CM/rep] box per col-block (mapQ is built
1499	    // accordingly by the launcher). Both land in the same swizzled tile gather_row_k would have built, so
1500	    // the per-item Q reload is one async TMA (not a 128-row cp.async gather) -- which is what makes the
1501	    // persistent ring WIN for GQA/MQA (the gather reload serialized and lost to the per-tile grid).
1502	    // Paged / rep-not-dividing-CM keep the cp.async gather.
1503	    // Q is NEVER paged (only K/V) -> Q can use TMA even when K/V uses the cp.async COOP gather (USE_TMA=0).
1504	    // TMA_Q decouples this (FA3: Use_TMA_Q independent of Use_TMA_KV): the paged persist launches TMA_Q=1
1505	    // so the per-work-item Q reload is ONE async TMA box (cheap) instead of the 128-lane cp.async gather --
1506	    // the reason the paged persist previously lost to the per-tile grid.
1507	    const bool tmaq     = TMA_Q && (rep == 1);
1508	    const bool tmaq_gqa = TMA_Q && (rep > 1) && (CM % rep == 0);
1509	    const int tid = threadIdx.x;
1510	    if (tid == 0) {
1511	#pragma unroll
1512	        for (int s = 0; s < STAGES; ++s) { mbar_init(&full[s], USE_TMA ? 1 : NumProd); mbar_init(&empty[s], NCONS); }
