1520	    // Dynamic LPT-free balancing: instead of static work=blockIdx.x+k*gridDim.x (which strands the
1521	    // causal triangular load -- early m-tiles are light, late ones heavy -- on fixed CTAs), each CTA
1522	    // pulls the next tile from a global atomic counter. The producer's lead thread grabs + publishes the
1523	    // index through a tiny smem FIFO (schW/schF/schE) so both warpgroups process the SAME stream while
1524	    // the GPU load-balances across CTAs the way the HW block scheduler does for the per-tile grid.
1525	    const int total_work = tiles_m * hkv * batch;
1526	    const int wg = tid / WG;
1527	
1528	    if (wg == 0) {
1529	        // ---------- producer ----------
1530	        producer_regs();
1531	        const int pt = tid;
1532	        constexpr int KBOX = HD / 64, VBOX = HDV / 64, CB = CN * 64;
1533	        const bool np = (page_table == nullptr);                      // non-paged contiguous KV
1534	        const int pages = np ? 0 : (CN / block_size);
1535	        const uint32_t kv_bytes = (uint32_t)((CN * HD + CN * HDV) * sizeof(TC));
1536	        // COOP gather constants (non-TMA paged persist). FA3 granularity: TPR=8 lanes/row, KIT=HD/64
1537	        // 16B chunks per lane (128-byte coalesced bursts). Barrier-free __shfl page resolve (see prefill_kernel).
1538	        constexpr int TPR = 8, KIT = HD / 64, RPP = WG / TPR, RPT = CN / RPP;
1539	        const int col_th = pt % TPR, rowsub = pt / TPR;
1540	        const int rsw = (pt & 31) / TPR;
1541	        int g = 0, witer = 0;
1542	        for (int it = 0; ; ++it) {
1543	            // Dynamic work-stealing via a global atomic (greedy balance for the causal triangular load;
1544	            // static round-robin regressed -- worse balance). pt==0 grabs + publishes via schW, the producer
1545	            // warpgroup broadcasts it (bar.sync), and pt==0 signals schF for the consumers.
1546	            const int sslot = it % SDEPTH;
1547	            if (pt == 0 && it >= SDEPTH) { int ep = ((it / SDEPTH) - 1) & 1; while (!mbar_try_wait(&schE[sslot], ep)) {} }
1548	            if (pt == 0) schW[sslot] = atomicAdd(work_ctr, 1);
1549	            asm volatile("bar.sync 1, %0;\n" :: "r"(WG) : "memory");
1550	            const int work = schW[sslot];
1551	            if (pt == 0) { __threadfence_block(); mbar_arrive(&schF[sslot]); }
1552	            if (work >= total_work) break;
1553	            PfTile t = pf_work<CN, CM, EXTRA>(work, tiles_m, hkv, rep, cu_q, cu_k, seqused_k,
1554	                                              causal, win_l, win_r, scale, q_descale, k_descale, v_descale, ds_b, ds_h);
1555	            if (!t.valid) continue;
1556	            const int gbase = g;
1557	            g += t.n_cnt;
1558	            const int bi = pf_bi(work, tiles_m, hkv);
1559	            const int last_pg = np ? 0 : ((t.seqlen_k - 1) / block_size);
1560	            const int ybase = np ? (cu_k ? cu_k[bi] : 0) : 0;         // non-paged: absolute key row of req bi
1561	            const int xk = t.hk * HD, xv = t.hk * HDV;
1562	            // load absolute key-tile nb into ring stage (gg % STAGES); pt==0 issues the TMA boxes.
1563	            // empty-gate on the GLOBAL gg keeps the ring a single continuous stream across items.
1564	            auto load_kv = [&](int gg, int nb) {
1565	                const int st = gg % STAGES;
1566	                if (gg >= STAGES) { int ep = ((gg / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1567	                TC* sKp = sK0 + st * KSTRIDE;
1568	                TC* sVp = sV0 + st * VSTRIDE;
1569	                mbar_expect_tx(&full[st], kv_bytes);
1570	                if (np) {
1571	                    // contiguous (non-paged): ONE [CN,64] box per col-block (same swizzled layout as paged).
1572	                    const int yk = ybase + nb * CN;
1573	#pragma unroll
1574	                    for (int bx = 0; bx < KBOX; ++bx) tma_box(sKp + bx * CB, &mapK, xk + bx * 64, yk, &full[st]);
1575	#pragma unroll
1576	                    for (int bx = 0; bx < VBOX; ++bx) tma_box(sVp + bx * CB, &mapV, xv + bx * 64, yk, &full[st]);
1577	                } else {
1578	                    for (int p = 0; p < pages; ++p) {
1579	                        int pg = nb * pages + p; if (pg > last_pg) pg = last_pg;
1580	                        int yrow = page_table[(long)bi * page_stride + pg] * block_size;
1581	                        int boff = p * block_size * 64;
1582	#pragma unroll
1583	                        for (int bx = 0; bx < KBOX; ++bx) tma_box(sKp + boff + bx * CB, &mapK, xk + bx * 64, yrow, &full[st]);
1584	#pragma unroll
1585	                        for (int bx = 0; bx < VBOX; ++bx) tma_box(sVp + boff + bx * CB, &mapV, xv + bx * 64, yrow, &full[st]);
1586	                    }
1587	                }
1588	            };
1589	            // Non-TMA paged variant: all 128 producer lanes cooperate on the barrier-free spread gather
1590	            // (see prefill_kernel COOP). full[] is inited to NumProd for !USE_TMA, so each lane arrives via
1591	            // cp_async_mbar_arrive (PF_PUBLISH). HD==HDV==128 only (COOP invariant); other HD stay on TMA.
1592	            auto load_kv_coop = [&](int gg, int nb) {
1593	                const int st = gg % STAGES;
1594	                if (gg >= STAGES) { int ep = ((gg / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1595	                TC* sKp = sK0 + st * KSTRIDE; TC* sVp = sV0 + st * VSTRIDE;
1596	                const uint32_t sKa = (uint32_t)__cvta_generic_to_shared(sKp);
1597	                const uint32_t sVa = (uint32_t)__cvta_generic_to_shared(sVp);
1598	                int ent = -1;
1599	                if (col_th < RPT) {
1600	                    const int key = nb * CN + rowsub + col_th * RPP;
1601	                    const bool kv = key < t.seqlen_k;
1602	                    if (page_table) {
1603	                        int blk = kv ? page_table[(long)bi * page_stride + key / block_size] : -1;
1604	                        ent = kv ? blk * block_size + (key % block_size) : -1;
1605	                    } else {
1606	                        ent = kv ? (ybase + key) : -1;
1607	                    }
1608	                }
1609	#pragma unroll
1610	                for (int r = 0; r < RPT; ++r) {
1611	                    const int row = rowsub + r * RPP;
1612	                    const long krow = __shfl_sync(0xffffffffu, ent, rsw * TPR + r, 32);
1613	#pragma unroll
1614	                    for (int ki = 0; ki < KIT; ++ki) {
1615	                        const int cc = ki * 64 + col_th * 8;
1616	                        const int ok = koffR<CN>(row, cc), ov = voffR<CN>(row, cc);
1617	                        if (krow >= 0) {
1618	                            cp_async_16(sKa + (uint32_t)(ok * 2), K + krow * k_row + (long)t.hk * k_head + cc);
1619	                            cp_async_16(sVa + (uint32_t)(ov * 2), V + krow * v_row + (long)t.hk * v_head + cc);
1620	                        } else {
1621	                            *reinterpret_cast<uint4*>(sKp + ok) = make_uint4(0, 0, 0, 0);
1622	                            *reinterpret_cast<uint4*>(sVp + ov) = make_uint4(0, 0, 0, 0);
1623	                        }
1624	                    }
1625	                }
1626	                PF_PUBLISH(&full[st]);
1627	            };
1628	            // (1) FIRST K/V tile before the Q-free wait -> primes the ring across the item boundary.
1629	            if constexpr (USE_TMA) { if (pt == 0) load_kv(gbase, t.n_lo); }
1630	            else                   load_kv_coop(gbase, t.n_lo);
1631	            // (2) Q into buffer slot witer%QBUF: wait the consumer freed it (item witer-QBUF), reload,
1632	            //     signal. rep==1 reloads via ONE TMA box-set; GQA/paged fall back to the cp.async gather.
1633	            const int qslot = witer % QBUF;
1634	            const int qcyc = witer / QBUF;
1635	            TC* sQs = sQ + qslot * (CM * HDsm);
1636	            if (witer >= QBUF) { int p = (qcyc - 1) & 1; while (!mbar_try_wait(&barQe[qslot], p)) {} }
1637	            if (tmaq) {
1638	                if (pt == 0) {
1639	                    mbar_expect_tx(&barQf[qslot], (uint32_t)(CM * HD * (int)sizeof(TC)));
1640	                    const int yq = t.q0 + t.row0, xq = t.hk * HD;  // rep==1 -> qhead == hk
1641	                    constexpr int QBOX = HD / 64;
1642	#pragma unroll
1643	                    for (int bx = 0; bx < QBOX; ++bx) tma_box(sQs + bx * (CM * 64), &mapQ, xq + bx * 64, yq, &barQf[qslot]);
1644	                }
1645	            } else if (tmaq_gqa) {
1646	                if (pt == 0) {
1647	                    mbar_expect_tx(&barQf[qslot], (uint32_t)(CM * HD * (int)sizeof(TC)));
1648	                    // 3D box: token z = q0 + row0/rep (rep|CM => row0/rep is the tile's first token),
1649	                    // head y = hk*rep, col x = bx*64. One box per col-block fills the [CM,64] swizzle tile.
1650	                    const int zq = t.q0 + t.row0 / rep, yq = t.hk * rep;
1651	                    constexpr int QBOX = HD / 64;
1652	#pragma unroll
1653	                    for (int bx = 0; bx < QBOX; ++bx) tma_box3(sQs + bx * (CM * 64), &mapQ, bx * 64, yq, zq, &barQf[qslot]);
1654	                }
1655	            } else if ((rep & (rep - 1)) == 0) {
1656	                // Coalesced Q reload (pow2 rep -> shift/mask, no runtime div): 8 lanes/row x KIT 16B chunks
1657	                // = 128-byte bursts (matches K/V COOP). This is the FIX that makes the persistent ring beat
1658	                // the per-tile grid for paged prefill -- the uncoalesced per-work-item Q reload was its loss.
1659	                const int rlog = 31 - __clz(rep), rmask = rep - 1;
1660	                const uint32_t sQsa = (uint32_t)__cvta_generic_to_shared(sQs);
1661	                constexpr int QRPT = (CM + RPP - 1) / RPP;
1662	#pragma unroll
1663	                for (int qr = 0; qr < QRPT; ++qr) {
1664	                    const int row = rowsub + qr * RPP;
1665	                    if (row < CM) {
1666	                        const int ii = t.row0 + row;
1667	                        const bool qval = ii < t.Mrows;
1668	                        const int token = qval ? (ii >> rlog) : 0;
1669	                        const int qhead = t.hk * rep + (qval ? (ii & rmask) : 0);
1670	                        const TIn* qsrc = Q + (long)(t.q0 + token) * q_row + (long)qhead * q_head;
1671	#pragma unroll
1672	                        for (int ki = 0; ki < KIT; ++ki) {
1673	                            const int cc = ki * 64 + col_th * 8;
1674	                            const int o = koffR<CM>(row, cc);
1675	                            if (qval) cp_async_16(sQsa + (uint32_t)(o * 2), qsrc + cc);
1676	                            else *reinterpret_cast<uint4*>(sQs + o) = make_uint4(0, 0, 0, 0);
1677	                        }
1678	                    }
1679	                }
1680	                PF_PUBLISH(&barQf[qslot]);
1681	            } else {
1682	                const int idx = t.row0 + pt;
1683	                const bool qval = idx < t.Mrows;
1684	                const int token = qval ? idx / rep : 0;
1685	                const int qhead = t.hk * rep + (qval ? idx % rep : 0);
1686	                const TIn* qsrc = Q + (long)(t.q0 + token) * q_row + (long)qhead * q_head;
1687	                gather_row_k<TIn, TC, HD, CM>(sQs, (uint32_t)__cvta_generic_to_shared(sQs), pt, qsrc, qval);
1688	                PF_PUBLISH(&barQf[qslot]);
1689	            }
1690	            // (3) remaining K/V tiles flood in behind Q.
1691	            if constexpr (USE_TMA) { if (pt == 0) for (int li = 1; li < t.n_cnt; ++li) load_kv(gbase + li, t.n_lo + li); }
1692	            else                   for (int li = 1; li < t.n_cnt; ++li) load_kv_coop(gbase + li, t.n_lo + li);
1693	            witer++;
1694	        }
1695	        return;
1696	    }
