1698	    // ---------- consumers ----------
1699	    // NOTE: tried lifting the consumer to 240 by ceding the producer to 24 (256*240+128*24 = the 64512
1700	    // pool) -- it regressed broadly (gqa 0.91->0.87, large4k 0.82->0.78): the TMA producer needs its 40
1701	    // regs to issue/schedule ahead, and starving it stalls the whole ring. Consumer stays at 232.
1702	    consumer_regs<(MINB >= 2) ? 128 : 232>();
1703	    const int cwg = wg - 1;
1704	    const int wtid = tid % WG, warp = wtid >> 5, lane = wtid & 31;
1705	    const int group = lane >> 2, tg = lane & 3;
1706	    const int row_lo = cwg * 64 + warp * 16 + group, row_hi = row_lo + 8;
1707	    const uint32_t sQ_base = (uint32_t)__cvta_generic_to_shared(sQ) + (uint32_t)(cwg * 4096 * (int)sizeof(TC));
1708	    const uint32_t sQ_slot = (uint32_t)(CM * HDsm * (int)sizeof(TC));   // stride between Q double-buffers
1709	    const uint32_t sK_a = (uint32_t)__cvta_generic_to_shared(sK0);
1710	    const uint32_t sV_a = (uint32_t)__cvta_generic_to_shared(sV0);
1711	    const uint32_t stK_bytes = (uint32_t)(KSTRIDE * (int)sizeof(TC));
1712	    const uint32_t stV_bytes = (uint32_t)(VSTRIDE * (int)sizeof(TC));
1713	
1714	    // Inter-WG ping-pong (mirrors prefill_kernel): the two consumer WGs process the SAME work item in
