909	// with the SAME work index so they agree on n_cnt (and thus the global ring counter g advances in
910	// lock-step). Mirrors the per-tile prefill_kernel coordinate/bounds math, minus split-KV (prefill
911	// runs num_splits==1). m_block is LPT-reversed (largest causal tile first) for static-strided balance.
912	struct PfTile {
913	    bool valid;
914	    int q0, hk, seqlen_q, seqlen_k, Mrows, row0, delta, n_lo, n_cnt;
915	    float sc_eff, s2, vd;
916	};
917	template <int CN, int CM, bool EXTRA>
918	__device__ __forceinline__ PfTile pf_work(
919	        int work, int tiles_m, int hkv, int rep,
920	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
921	        int causal, int win_l, int win_r, float scale,
922	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
923	        const float* __restrict__ v_descale, int ds_b, int ds_h) {
924	    PfTile t; t.valid = false;
925	    const int hb = tiles_m * hkv;
926	    const int bi = work / hb;
927	    const int rem = work - bi * hb;
928	    t.hk = rem / tiles_m;
929	    const int m_block = (tiles_m - 1) - (rem - t.hk * tiles_m);   // LPT: largest causal tile first
930	    t.q0 = cu_q[bi];
931	    t.seqlen_q = cu_q[bi + 1] - t.q0;
932	    t.seqlen_k = seqused_k ? seqused_k[bi] : (cu_k[bi + 1] - cu_k[bi]);
933	    t.Mrows = t.seqlen_q * rep;
934	    t.row0 = m_block * CM;
935	    if (t.row0 >= t.Mrows || t.seqlen_k <= 0) return t;            // padded m_block / empty seq
936	    t.delta = t.seqlen_k - t.seqlen_q;
937	    const long ds_idx = (long)bi * ds_b + (long)t.hk * ds_h;
938	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
939	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
940	    t.vd = v_descale ? v_descale[ds_idx] : 1.f;
941	    t.sc_eff = scale * qd * kd;
942	    t.s2 = t.sc_eff * float(M_LOG2E);
943	    const int top = (t.row0 + CM - 1 < t.Mrows - 1) ? (t.row0 + CM - 1) : (t.Mrows - 1);
944	    const int qabs_max = (top / rep) + t.delta;
945	    int n_max = causal ? ((qabs_max + 1 + CN - 1) / CN) : ((t.seqlen_k + CN - 1) / CN);
946	    int n_beg = 0;
947	    if constexpr (EXTRA) {
948	        if (win_l >= 0) { int lo = (t.row0 / rep) + t.delta - win_l; if (lo > 0) n_beg = lo / CN; }
949	        if (!causal && win_r >= 0) { int tt = (qabs_max + win_r) / CN + 1; if (tt < n_max) n_max = tt; }
950	    }
951	    if (n_beg >= n_max) return t;                                  // fully masked
952	    t.n_lo = n_beg; t.n_cnt = n_max - n_beg;
953	    t.valid = true;
954	    return t;
955	}
