2460	static void launch_prefill_t(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2461	                             at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2462	                             const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2463	                             const std::optional<at::Tensor>& page_table, const CUtensorMap& mapK,
2464	                             const CUtensorMap& mapV, int hkv, int rep, int total_q, int block_size,
2465	                             int page_stride, int tiles_m, int b, double scale, bool causal,
2466	                             double softcap, int win_l, int win_r,
2467	                             long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2468	                             long o_row, long o_head, int num_splits, float* Opart, float* LSEpart,
2469	                             const float* qd, const float* kd, const float* vd, int ds_b, int ds_h,
2470	                             const float* s_aux, const int* leftpad_k,
2471	                             cudaStream_t stream) {
2472	    const bool paged = page_table.has_value();
2473	    constexpr int HDsm = ((HD + 63) / 64) * 64, HDVsm = ((HDV + 63) / 64) * 64;
2474	    constexpr int NTHR = WG * (1 + CM / 64);   // 1 producer WG + CM/64 consumer WGs
2475	
2476	    // Persistent continuous-ring prefill: collapses the per-tile grid's ~8.7 waves into 1 (recovering
2477	    // the 14%->18.7% inter-wave SM-residency gap that bounds the big-head / long-context dense configs).
2478	    // The lever that makes it WIN (vs the earlier single/double-Q gather attempts that regressed): Q is
2479	    // reloaded per item via ONE async TMA (rep==1 contiguous), fast enough that the STAGES-deep K/V ring
2480	    // hides it -> single-Q fits the full ring (no double-Q smem squeeze that forced STAGES=2 and starved
2481	    // the pipe). Scoped to rep==1 + contiguous Q/KV: the rep>1 cp.async-gather Q reload serializes on the
2482	    // single-Q handshake and lost to the per-tile grid (gqa 0.82->0.78, mqa 0.82->0.77), so GQA/MQA/
2483	    // paged/varlen stay on the per-tile grid.
2484	    constexpr int PSTAGES = STAGES;
2485	    constexpr bool PF_PERSIST = true;
2486	    // CM==64 persist is enabled ONLY for big heads (HD>=192): the hd256 dense-prefill wide-CN path uses
2487	    // a half-height Q tile so a wider K/V tile fits at STAGES=3 (the ping-pong is off for HD>128 anyway).
2488	    // Scoping to HD>=192 keeps the CM=64 decode-split path (hd<=128, which also calls launch_prefill_t)
2489	    // on its per-tile grid -- only the non-paged single-split big-head prefill reaches this branch.
2490	    if constexpr (PF_PERSIST && (CM == 128 || (CM == 64 && HD >= 192)) && TMA && std::is_same<TIn, TC>::value) {
2491	        static int num_sm = 0;
2492	        if (num_sm == 0) { int dev = 0; cudaGetDevice(&dev); cudaDeviceGetAttribute(&num_sm, cudaDevAttrMultiProcessorCount, dev); if (num_sm <= 0) num_sm = 132; }
2493	        const long total_work = (long)tiles_m * hkv * b;
2494	        const bool q_contig = (q.stride(2) == 1) && (q.stride(1) == (int64_t)HD);
2495	        // rep==1 -> 2D contiguous Q box; packed-GQA (rep>1, rep|CM) -> 3D Q box. Both reload Q via one
2496	        // async TMA so the persistent ring's per-item Q cost stays hidden (the gather reload regressed).
2497	        const bool persist_q_ok = q_contig && (rep == 1 || (rep > 1 && (CM % rep == 0)));
2498	        if (!paged && persist_q_ok && num_splits <= 1 && total_work >= 2L * num_sm) {
2499	            CUtensorMap mapQ = (rep == 1) ? make_kv_map_contig<TC>(q, CM) : make_q_map_gqa<TC>(q, rep, CM);
